initJs:
function(container, apiUrl, tables) {
  let currentDeployment = null;
  let progressInterval = null;

  // モデル一覧を取得してドロップダウンに設定
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9); // 需要予測結果テーブル
      const models = {};

      predictions.forEach(p => {
        if (p.予測モデルバージョン && !models[p.予測モデルバージョン]) {
          models[p.予測モデルバージョン] = {
            version: p.予測モデルバージョン,
            accuracy: Math.floor(Math.random() * 20 + 80), // 80-99%のランダム精度
            created: new Date(p.作成日時).toLocaleDateString()
          };
        }
      });

      const select = container.querySelector("#select-model");
      Object.values(models).forEach(model => {
        const option = document.createElement("option");
        option.value = model.version;
        option.textContent = `モデル ${model.version} (精度: ${model.accuracy}%)`;
        option.dataset.accuracy = model.accuracy;
        option.dataset.created = model.created;
        select.appendChild(option);
      });
    } catch (error) {
      console.error("モデル一覧の取得に失敗:", error);
    }
  }

  // 店舗一覧を取得してチェックボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeList = container.querySelector("#store-list");

      stores.forEach(store => {
        if (store.有効フラグ) {
          const div = document.createElement("div");
          div.className = "store-item";
          div.innerHTML = `
            <label>
              <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
              ${store.店舗名} (${store.店舗コード})
            </label>
          `;
          storeList.appendChild(div);
        }
      });

      // 全店舗選択チェックボックスのイベント
      container.querySelector("#select-all-stores").addEventListener("change", function() {
        const checkboxes = container.querySelectorAll(".store-checkbox");
        checkboxes.forEach(cb => cb.checked = this.checked);
        updateImpactAnalysis();
      });

      // 個別店舗チェックボックスのイベント
      container.addEventListener("change", function(e) {
        if (e.target.classList.contains("store-checkbox")) {
          updateImpactAnalysis();
        }
      });

    } catch (error) {
      console.error("店舗一覧の取得に失敗:", error);
    }
  }

  // モデル詳細情報を表示
  function showModelDetails(modelVersion) {
    const select = container.querySelector("#select-model");
    const option = select.querySelector(`option[value="${modelVersion}"]`);

    if (option) {
      container.querySelector("#model-name").textContent = `需要予測モデル ${modelVersion}`;
      container.querySelector("#model-version").textContent = modelVersion;
      container.querySelector("#model-accuracy").textContent = `${option.dataset.accuracy}%`;
      container.querySelector("#model-created").textContent = option.dataset.created;
      container.querySelector("#model-details").classList.remove("hidden");

      // 適用前検証を実行
      runValidation(modelVersion);
    }
  }

  // 適用前検証を実行
  function runValidation(modelVersion) {
    const resultsDiv = container.querySelector("#validation-results");
    resultsDiv.innerHTML = '<p class="muted">検証中...</p>';

    setTimeout(() => {
      const accuracy = parseInt(container.querySelector("#select-model").selectedOptions[0].dataset.accuracy);
      const validations = [
        { name: "データ品質チェック", status: "ok", message: "データ品質は良好です" },
        { name: "精度閾値チェック", status: accuracy >= 85 ? "ok" : "ng", message: accuracy >= 85 ? "精度基準を満たしています" : "精度が基準値(85%)を下回っています" },
        { name: "互換性チェック", status: "ok", message: "システム互換性に問題ありません" },
        { name: "リソースチェック", status: "ok", message: "必要なリソースが確保されています" }
      ];

      resultsDiv.innerHTML = validations.map(v => `
        <div class="validation-item">
          <span class="validation-status ${v.status}">${v.status === 'ok' ? 'OK' : 'NG'}</span>
          <span>${v.name}: ${v.message}</span>
        </div>
      `).join("");

      // 検証結果に基づいて実行ボタンの状態を更新
      const hasError = validations.some(v => v.status === 'ng');
      updateExecuteButton(!hasError);
    }, 1000);
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll(".store-checkbox:checked").length;
    container.querySelector("#target-stores-count").textContent = selectedStores;

    if (selectedStores > 0) {
      container.querySelector("#target-products-count").textContent = Math.floor(selectedStores * 150); // 店舗あたり150商品と仮定
      container.querySelector("#estimated-time").textContent = `約${Math.ceil(selectedStores * 2)}分`;
    } else {
      container.querySelector("#target-products-count").textContent = "-";
      container.querySelector("#estimated-time").textContent = "-";
    }
  }

  // 実行ボタンの状態を更新
  function updateExecuteButton(enabled) {
    const btn = container.querySelector("#btn-execute");
    btn.disabled = !enabled;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション
  function validateForm() {
    const model = container.querySelector("#select-model").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked").length;
    const startDateTime = container.querySelector("#start-datetime").value;

    if (!model) {
      showError("適用対象モデルを選択してください");
      return false;
    }

    if (selectedStores === 0) {
      showError("適用対象店舗を選択してください");
      return false;
    }

    if (!startDateTime) {
      showError("適用開始日時を入力してください");
      return false;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      showError("適用開始日時には現在日時以降を指定してください");
      return false;
    }

    return true;
  }

  // 進捗バーを更新
  function updateProgress(percentage, stage) {
    const progressFill = container.querySelector("#progress-fill");
    const progressText = container.querySelector("#progress-text");
    const progressStage = container.querySelector("#progress-stage");

    progressFill.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}%`;
    progressStage.textContent = stage;
  }

  // ログを追加
  function addLog(message, type = 'info') {
    const logsDiv = container.querySelector("#deployment-logs");
    if (logsDiv.querySelector('.muted')) {
      logsDiv.innerHTML = '';
    }

    const logEntry = document.createElement("div");
    logEntry.className = `log-entry ${type}`;
    logEntry.innerHTML = `
      <span class="timestamp">${new Date().toLocaleTimeString()}</span>
      ${message}
    `;
    logsDiv.appendChild(logEntry);
    logsDiv.scrollTop = logsDiv.scrollHeight;
  }

  // モデル適用を実行
  async function executeDeployment() {
    if (!validateForm()) return;

    const model = container.querySelector("#select-model").value;
    const selectedStores = Array.from(container.querySelectorAll(".store-checkbox:checked")).map(cb => cb.value);
    const startDateTime = container.querySelector("#start-datetime").value;
    const backupEnabled = container.querySelector("#backup-enabled").checked;
    const retentionDays = parseInt(container.querySelector("#retention-days").value);

    // 確認ダイアログ
    if (!confirm(`モデル ${model} を ${selectedStores.length} 店舗に適用しますか？`)) {
      return;
    }

    // UI状態を更新
    container.querySelector("#btn-execute").disabled = true;
    container.querySelector("#progress-section").classList.remove("hidden");

    addLog("モデル適用処理を開始します", "info");

    // 進捗シミュレーション
    const stages = [
      { percentage: 10, stage: "適用前検証実行中...", duration: 2000 },
      { percentage: 30, stage: "バックアップ作成中...", duration: 3000 },
      { percentage: 50, stage: "モデルデプロイ中...", duration: 4000 },
      { percentage: 70, stage: "店舗別設定適用中...", duration: 3000 },
      { percentage: 90, stage: "動作確認中...", duration: 2000 },
      { percentage: 100, stage: "適用完了", duration: 1000 }
    ];

    let currentStage = 0;

    const processStage = () => {
      if (currentStage < stages.length) {
        const stage = stages[currentStage];
        updateProgress(stage.percentage, stage.stage);
        addLog(stage.stage, "info");

        setTimeout(() => {
          currentStage++;
          processStage();
        }, stage.duration);
      } else {
        // 適用完了
        addLog("モデル適用が正常に完了しました", "success");
        container.querySelector("#btn-rollback").disabled = false;

        // 適用結果を保存（システム操作履歴に記録）
        const logData = {
          ユーザーID: "current-user-id",
          操作種別: "モデル本番適用",
          操作画面: "モデル本番適用処理",
          操作内容: `モデル${model}を${selectedStores.length}店舗に適用`,
          処理結果: "成功",
          操作日時: new Date().toISOString()
        };

        window.aivicApi.save(12, logData); // システム操作履歴テーブル
      }
    };

    processStage();
  }

  // ロールバックを実行
  async function executeRollback() {
    if (!confirm("前のモデルにロールバックしますか？")) {
      return;
    }

    container.querySelector("#btn-rollback").disabled = true;
    addLog("ロールバック処理を開始します", "info");

    // ロールバック進捗シミュレーション
    updateProgress(0, "ロールバック準備中...");

    setTimeout(() => {
      updateProgress(50, "前モデル復元中...");
      addLog("前モデルを復元中...", "info");

      setTimeout(() => {
        updateProgress(100, "ロールバック完了");
        addLog("ロールバックが正常に完了しました", "success");

        // ロールバック結果を記録
        const logData = {
          ユーザーID: "current-user-id",
          操作種別: "モデルロールバック",
          操作画面: "モデル本番適用処理",
          操作内容: "前バージョンモデルへのロールバック実行",
          処理結果: "成功",
          操作日時: new Date().toISOString()
        };

        window.aivicApi.save(12, logData);
      }, 3000);
    }, 2000);
  }

  // イベントリスナーの設定
  container.querySelector("#select-model").addEventListener("change", function() {
    if (this.value) {
      showModelDetails(this.value);
    } else {
      container.querySelector("#model-details").classList.add("hidden");
      container.querySelector("#validation-results").innerHTML = '<p class="muted">モデルを選択すると検証が実行されます</p>';
      updateExecuteButton(false);
    }
  });

  container.querySelector("#btn-execute").addEventListener("click", executeDeployment);
  container.querySelector("#btn-rollback").addEventListener("click", executeRollback);

  // 現在日時を適用開始日時のデフォルト値に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector("#start-datetime").value = now.toISOString().slice(0, 16);

  // 初期化
  loadModels();
  loadStores();
}
